// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount, address caller) public {
        bound(amount, 0, address(c).balance);
        vm.assume(caller != c.owner());

        address recordedOwner = c.owner();

        vm.deal(address(c), amount);

        vm.prank(caller);
        bool ok = false;
        try c.sendMoney(target, amount) { ok = true; } catch { ok = false; }

        uint256 balanceAfter = address(c).balance;
        assertEq(balanceAfter, amount);
    }
}
